def translate_cell(s):
    if s in T: return T[s]
    if ', ' in s and re.fullmatch(r'[\d, ]+',s): return s
    # Localize only pure numerical cells / numerical values with units.
    if re.fullmatch(r'[\d.,% /−-]+(?: flow| giây)?',s):
        return s.replace('.', '\x00').replace(',', '.').replace('\x00', ',').replace(' flow',' flows').replace(' giây',' seconds')
    if re.search(r'[àáảãạăâđèéẻẽẹêìíỉĩịòóỏõọôơùúủũụưỳýỷỹỵ]',s,re.I):
        raise ValueError('Untranslated cell: '+s)
    return s

def replace_paragraph(p,text):
    # Keep paragraph properties and the first text run's formatting.
    runs=[r for r in p.runs if r.text]
    if runs:
        runs[0].text=text
        for r in runs[1:]: r.text=''
    else: p.add_run(text)
    for r in p.runs:
        rp=r._element.get_or_add_rPr()
        lang=rp.find(qn('w:lang'))
        if lang is not None: lang.set(qn('w:val'),'en-US')

def build():
    d=Document(SRC)
    nonempty={i for i,p in enumerate(d.paragraphs) if p.text.strip()}
    assert nonempty==set(P), (nonempty-set(P),set(P)-nonempty)
    for i,text in P.items(): replace_paragraph(d.paragraphs[i],text)
    for table in d.tables:
        for row in table.rows:
            for cell in row.cells:
                for p in cell.paragraphs:
                    if p.text: replace_paragraph(p,translate_cell(p.text))
    qa=ROOT/'Report/.qa_en'
    replacements={7:'research.png',51:'architecture.png',82:'class_distribution.png',105:'confusion_matrix.png',117:'lime_agreement.png',128:'noise_robustness.png',135:'faithfulness.png',165:'live_timeline.png',180:'pcap_shap.png'}
    for index,name in replacements.items():
        p=d.paragraphs[index]
        embeds=p._element.xpath('.//a:blip')
        assert len(embeds)==1,(index,len(embeds))
        part=d.part.related_parts[embeds[0].get(qn('r:embed'))]
        part._blob=(qa/name).read_bytes()
    d.save(OUT)
    check=Document(OUT)
    assert len(check.tables)==21 and len(check.inline_shapes)==9
    assert len(check.paragraphs)==len(d.paragraphs)==212
    (qa/'translation_map.json').write_text(json.dumps({'paragraphs':P,'cells':T},ensure_ascii=False,indent=2),encoding='utf-8')
    print(OUT)

if __name__=='__main__': build()
